#include <stdio.h>

int main() {
    char arr[] = "hello";  // 스택에 복사
    char *ptr = "hello";    // 읽기전용 영역 가리킴

    arr[0] = 'H';  // OK! 수정 가능
    printf("arr: %s\n", arr);

    // ptr[0] = 'H';  // 위험! Segmentation fault

    printf("arr 주소: %p\n", arr);
    printf("ptr 주소: %p\n", ptr);

    return 0;
}
